//! AD CS checks against `testdata/adcs` (generated by
//! `scripts/gen_adcs_fixture.py`). PKI.LOCAL has one eligible CA (PKI-CA:
//! enabled host CA01, own root, in NTAuth) and one ineligible CA (ROGUE-CA: not in
//! NTAuth). Planted conditions:
//!
//! - ESC1: VULNWEB, enrollee supplies subject, enrollable by WEBADMINS (BOB)
//! - ESC3: ENROLLMENTAGENT (AGENTS: ALICE) can enroll USER (schema 1) for anyone
//! - ESC4: BOB has WriteDacl on USER
//! - ESC6a: PKI-CA has EDITF_ATTRIBUTESUBJECTALTNAME2; NOSECEXT enrollable by Domain Users
//! - ESC8: PKI-CA serves web enrollment over HTTP
//! - ESC11: PKI-CA's InterfaceFlags lack IF_ENFORCEENCRYPTICERTREQUEST (read by
//!   the built-in collector); ROGUE-CA's were not read
//! - ESC9a: NOSECEXT has no security extension and UPN SAN; CAROL can write DAVE
//! - ESC13: POLICYCERT's issuance policy links to Domain Admins; ALICE can enroll
//! - ESC7: FRANK holds ManageCA (registry); DAVE's ManageCA exists only in LDAP ACEs
//! - APPROVED supplies subject but needs manager approval: not ESC1
//! - DC01: StrongCertificateBindingEnforcement 1, Schannel mapping 0x18 (no UPN bit)

use std::collections::BTreeMap;

use petgraph::visit::EdgeRef;
use std::path::PathBuf;

use pathwarden_core::adcs::{Esc, EscInstance};
use pathwarden_core::findings::{self, Context, RuleSettings};
use pathwarden_core::model::{AdcsProps, EdgeKind};
use pathwarden_core::{load, remediation, AdGraph, IngestStats, LoadOptions};

fn fixture() -> (AdGraph, IngestStats) {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/adcs");
    load(&[dir], &LoadOptions::default()).expect("fixture loads")
}

fn name(g: &AdGraph, ix: pathwarden_core::NodeIndex) -> &str {
    g.node(ix).name.split('@').next().unwrap()
}

fn instances(g: &AdGraph) -> BTreeMap<Esc, Vec<&EscInstance>> {
    let mut out: BTreeMap<Esc, Vec<&EscInstance>> = BTreeMap::new();
    for i in g.esc_instances() {
        out.entry(i.esc).or_default().push(i);
    }
    out
}

fn sources<'a>(g: &'a AdGraph, i: &EscInstance) -> Vec<&'a str> {
    i.sources.iter().map(|&s| name(g, s)).collect()
}

fn only<'a>(map: &'a BTreeMap<Esc, Vec<&'a EscInstance>>, esc: Esc) -> &'a EscInstance {
    let list = map.get(&esc).unwrap_or_else(|| panic!("{esc:?} not found"));
    assert_eq!(list.len(), 1, "{esc:?}");
    list[0]
}

#[test]
fn detects_each_planted_esc() {
    let (g, _) = fixture();
    let by = instances(&g);
    let template = |i: &EscInstance| name(&g, i.template.unwrap()).to_string();

    let esc1 = only(&by, Esc::Esc1);
    assert_eq!(
        (template(esc1), sources(&g, esc1)),
        ("VULNWEB".into(), vec!["WEBADMINS"])
    );

    let esc3 = only(&by, Esc::Esc3);
    assert_eq!(template(esc3), "ENROLLMENTAGENT");
    assert_eq!(name(&g, esc3.related.unwrap()), "USER");
    assert_eq!(sources(&g, esc3), ["ALICE"]);

    let esc4 = only(&by, Esc::Esc4);
    assert_eq!(
        (template(esc4), sources(&g, esc4)),
        ("USER".into(), vec!["BOB"])
    );

    let esc6 = only(&by, Esc::Esc6a);
    assert_eq!(
        (template(esc6), sources(&g, esc6)),
        ("NOSECEXT".into(), vec!["DOMAIN USERS"])
    );
    assert!(
        !by.contains_key(&Esc::Esc6b),
        "no Schannel UPN mapping on DC01"
    );

    let esc8 = only(&by, Esc::Esc8);
    assert_eq!(name(&g, esc8.ca), "PKI-CA");

    // ESC11: every authentication template issued without approval or
    // signatures (not ENROLLMENTAGENT, not APPROVED).
    let mut esc11: Vec<String> = by[&Esc::Esc11].iter().map(|i| template(i)).collect();
    esc11.sort();
    assert_eq!(esc11, ["NOSECEXT", "POLICYCERT", "USER", "VULNWEB"]);
    assert!(by[&Esc::Esc11].iter().all(|i| name(&g, i.ca) == "PKI-CA"));

    let esc9 = only(&by, Esc::Esc9a);
    assert_eq!(sources(&g, esc9), ["CAROL"]);
    assert!(esc9.victims.iter().any(|&v| name(&g, v) == "DAVE"));
    assert!(!by.contains_key(&Esc::Esc10a) && !by.contains_key(&Esc::Esc10b));

    let esc13 = only(&by, Esc::Esc13);
    assert_eq!(sources(&g, esc13), ["ALICE"]);
    assert_eq!(name(&g, esc13.targets[0]), "DOMAIN ADMINS");
}

#[test]
fn ignores_ineligible_ca_and_approval_templates() {
    let (g, _) = fixture();
    for i in g.esc_instances() {
        assert_eq!(
            name(&g, i.ca),
            "PKI-CA",
            "ROGUE-CA is not trusted for NT auth"
        );
        assert_ne!(i.template.map(|t| name(&g, t)), Some("APPROVED"));
    }
}

#[test]
fn ca_permissions_follow_registry_security() {
    let (g, _) = fixture();
    let ca = g.find("PKI-CA")[0];
    let manage_ca: Vec<&str> = g
        .inner()
        .edges_directed(ca, petgraph::Direction::Incoming)
        .filter(|e| *e.weight() == EdgeKind::ManageCa)
        .map(|e| name(&g, e.source()))
        .collect();
    assert!(manage_ca.contains(&"FRANK"));
    assert!(
        !manage_ca.contains(&"DAVE"),
        "LDAP CA rights are superseded by registry security"
    );
    assert_eq!(
        manage_ca.len(),
        2,
        "local group entries are dropped: {manage_ca:?}"
    );
}

#[test]
fn ca_infrastructure_is_tier_zero() {
    let (g, _) = fixture();
    for n in [
        "CA01.PKI.LOCAL",
        "CA02.PKI.LOCAL",
        "PKI-CA",
        "PKI-CA ROOT",
        "NTAUTHCERTIFICATES",
    ] {
        let ix = g.find(n)[0];
        assert!(g.node(ix).tier_zero, "{n} should be Tier Zero");
    }
    let host = g.find("CA01.PKI.LOCAL")[0];
    assert!(g
        .inner()
        .edges_directed(host, petgraph::Direction::Outgoing)
        .any(|e| *e.weight() == EdgeKind::GoldenCert));
}

#[test]
fn findings_and_plan() {
    let (g, stats) = fixture();
    let settings = RuleSettings::default();
    let all = findings::evaluate(&Context::new(&g, &stats.trusts, &settings), &[]);
    let mut rules: Vec<&str> = all.iter().map(|f| f.rule).collect();
    rules.sort_unstable();
    rules.dedup();
    for r in [
        "PW-001", "PW-003", "PW-015", "PW-016", "PW-017", "PW-018", "PW-019", "PW-020", "PW-021",
        "PW-036",
    ] {
        assert!(rules.contains(&r), "{r} missing from {rules:?}");
    }
    // AD CS edges are reported by their ESC rule, not again as generic control.
    let pw003: Vec<&str> = all
        .iter()
        .filter(|f| f.rule == "PW-003")
        .map(|f| f.title.as_str())
        .collect();
    assert_eq!(pw003, ["FRANK@PKI.LOCAL has ManageCA on PKI-CA@PKI.LOCAL"]);

    // ROGUE-CA's SAN flag is not exploitable (not in NTAuth) but is reported as hygiene.
    let flag: Vec<&str> = all
        .iter()
        .filter(|f| {
            f.rule == "PW-018" && f.title.contains("EDITF_ATTRIBUTESUBJECTALTNAME2 enabled")
        })
        .map(|f| f.title.as_str())
        .collect();
    assert_eq!(
        flag,
        ["ROGUE-CA@PKI.LOCAL has EDITF_ATTRIBUTESUBJECTALTNAME2 enabled"]
    );

    // ESC4: the fix names the right BOB actually holds, and who keeps it.
    let esc4 = all.iter().find(|f| f.rule == "PW-017").unwrap();
    assert!(
        esc4.remediation.starts_with(
            "Remove these certificate template permissions on USER: Modify permissions of BOB@PKI.LOCAL."
        ),
        "{}",
        esc4.remediation
    );
    assert!(esc4.remediation.contains("Only the PKI administrators"));

    // ESC1: certificates already issued are reviewed.
    let esc1 = all.iter().find(|f| f.rule == "PW-015").unwrap();
    assert!(esc1
        .remediation
        .contains("Certificates it already issued stay valid"));

    // ESC11: one finding for the CA, naming the templates.
    let esc11: Vec<&findings::Finding> = all.iter().filter(|f| f.rule == "PW-036").collect();
    assert_eq!(esc11.len(), 1);
    assert_eq!(
        esc11[0].title,
        "ESC11: PKI-CA@PKI.LOCAL accepts relayed NTLM over RPC"
    );
    assert!(esc11[0]
        .summary
        .contains("NOSECEXT, POLICYCERT, USER, VULNWEB"));
    assert!(esc11[0]
        .remediation
        .contains("+IF_ENFORCEENCRYPTICERTREQUEST"));

    // ESC11 is checked only where the CA's InterfaceFlags were read.
    let checked: Vec<(String, bool)> = pathwarden_core::posture::adcs_completeness(&g)
        .into_iter()
        .map(|c| (c.ca, c.esc11))
        .collect();
    assert_eq!(
        checked,
        [
            ("PKI-CA@PKI.LOCAL".to_string(), true),
            ("ROGUE-CA@PKI.LOCAL".to_string(), false)
        ]
    );

    let plan = remediation::plan(&g, &pathwarden_core::analysis::Relevance::new(&g, 0, 90));
    assert!(plan.exposed_before > 0);
    assert_eq!(plan.exposed_after, 0);
}

#[test]
fn empty_eku_means_any_purpose_even_if_collector_says_otherwise() {
    // RustHound-CE reports authenticationenabled=false for an empty EKU list.
    let props: serde_json::Map<String, serde_json::Value> = serde_json::from_str(
        r#"{"effectiveekus": [], "authenticationenabled": false, "schemaversion": 2}"#,
    )
    .unwrap();
    let p = AdcsProps::from_map(&props);
    assert_eq!(p.authenticationenabled, Some(true));
    assert_eq!(p.schannelauthenticationenabled, Some(true));

    // Unknown stays unknown.
    let p = AdcsProps::from_map(&serde_json::Map::new());
    assert_eq!(p.authenticationenabled, None);
}

/// The fixture with DC01's registry block replaced: `binding` is the
/// StrongCertificateBindingEnforcement entry, as SharpHound writes it.
fn fixture_with_binding(tag: &str, binding: &str) -> (AdGraph, IngestStats) {
    let src = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/adcs");
    let dir = std::env::temp_dir().join(format!("pathwarden-adcs-{tag}-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    for entry in std::fs::read_dir(&src).unwrap() {
        let path = entry.unwrap().path();
        let mut text = std::fs::read_to_string(&path).unwrap();
        if path.file_name().unwrap() == "pki_computers.json" {
            let v: serde_json::Value = serde_json::from_str(&text).unwrap();
            let mut v = v;
            for c in v["data"].as_array_mut().unwrap() {
                if c.get("DCRegistryData").is_some_and(|d| !d.is_null()) {
                    c["DCRegistryData"]["StrongCertificateBindingEnforcement"] =
                        serde_json::from_str(binding).unwrap();
                }
            }
            text = v.to_string();
        }
        std::fs::write(dir.join(path.file_name().unwrap()), text).unwrap();
    }
    let out = load(std::slice::from_ref(&dir), &LoadOptions::default()).expect("fixture loads");
    let _ = std::fs::remove_dir_all(&dir);
    out
}

/// An ESC9 hijacker the collection doesn't hold: a principal of another
/// domain with GenericWrite on DAVE. RustHound-CE up to 2.5.29 typed such a
/// principal "Group"; from 2.5.30 (g0h4n/RustHound-CE#107) it is "Base".
/// Either way it can rewrite DAVE's UPN, so it is a source.
#[test]
fn an_unresolved_principal_writing_a_victim_is_an_esc9_source() {
    const FOREIGN: &str = "S-1-5-21-9000-9000-9000-1500";
    for kind in ["Group", "Base"] {
        let src = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/adcs");
        let dir = std::env::temp_dir().join(format!(
            "pathwarden-adcs-foreign-{kind}-{}",
            std::process::id()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        for entry in std::fs::read_dir(&src).unwrap() {
            let path = entry.unwrap().path();
            let mut text = std::fs::read_to_string(&path).unwrap();
            if path.file_name().unwrap() == "pki_users.json" {
                let mut v: serde_json::Value = serde_json::from_str(&text).unwrap();
                for u in v["data"].as_array_mut().unwrap() {
                    if u["Properties"]["name"] == "DAVE@PKI.LOCAL" {
                        u["Aces"].as_array_mut().unwrap().push(serde_json::json!({
                            "PrincipalSID": FOREIGN,
                            "PrincipalType": kind,
                            "RightName": "GenericWrite",
                            "IsInherited": false
                        }));
                    }
                }
                text = v.to_string();
            }
            std::fs::write(dir.join(path.file_name().unwrap()), text).unwrap();
        }
        let (g, _) = load(std::slice::from_ref(&dir), &LoadOptions::default()).unwrap();
        let _ = std::fs::remove_dir_all(&dir);
        let by = instances(&g);
        let esc9 = only(&by, Esc::Esc9a);
        let mut got = sources(&g, esc9);
        got.sort_unstable();
        assert_eq!(got, ["CAROL", FOREIGN], "typed {kind}");
    }
}

fn has_edge(g: &AdGraph, kind: EdgeKind) -> bool {
    g.inner().edge_references().any(|e| *e.weight() == kind)
}

#[test]
fn unreadable_dc_binding_is_unverified_not_an_attack_path() {
    // SharpHound without registry rights: Collected false and a placeholder 0,
    // which must not be read as "compatibility mode".
    let (g, stats) = fixture_with_binding(
        "uncollected",
        r#"{"Value": 0, "Collected": false, "FailureReason": "access denied"}"#,
    );
    let by = instances(&g);
    for esc in [Esc::Esc6a, Esc::Esc9a] {
        let i = only(&by, esc);
        assert!(i.targets.is_empty(), "{esc:?} has no confirmed target");
        assert_eq!(i.unverified.len(), 1, "{esc:?} is unverified for PKI.LOCAL");
    }
    assert!(!has_edge(&g, EdgeKind::AdcsEsc6a));
    assert!(!has_edge(&g, EdgeKind::AdcsEsc9a));

    let settings = RuleSettings::default();
    let ctx = Context::new(&g, &stats.trusts, &settings);
    let all = findings::evaluate(&ctx, &[]);
    let esc9 = all
        .iter()
        .find(|f| f.rule == "PW-020")
        .expect("ESC9 still reported");
    assert!(esc9.title.ends_with("(unverified)"), "{}", esc9.title);
    assert_eq!(esc9.category, findings::Category::Hygiene);
    assert_eq!(esc9.severity, findings::Severity::Medium);
    // ESC6 falls back to the CA flag finding, which needs no DC setting.
    let pki: Vec<_> = all
        .iter()
        .filter(|f| f.rule == "PW-018" && f.title.starts_with("PKI-CA"))
        .collect();
    assert_eq!(pki.len(), 1);
    assert!(
        pki[0].title.contains("EDITF_ATTRIBUTESUBJECTALTNAME2"),
        "{}",
        pki[0].title
    );
    assert_eq!(pki[0].severity, findings::Severity::High);
}

#[test]
fn full_enforcement_closes_esc6a_and_esc9a() {
    let (g, _) = fixture_with_binding("enforced", r#"{"Value": 2, "Collected": true}"#);
    let by = instances(&g);
    assert!(!by.contains_key(&Esc::Esc6a));
    assert!(!by.contains_key(&Esc::Esc9a));
    assert!(!has_edge(&g, EdgeKind::AdcsEsc9a));
}

#[test]
fn compatibility_mode_keeps_esc9a_an_attack_path() {
    let (g, _) = fixture();
    let by = instances(&g);
    let i = only(&by, Esc::Esc9a);
    assert_eq!(i.targets.len(), 1);
    assert!(i.unverified.is_empty());
    assert!(has_edge(&g, EdgeKind::AdcsEsc9a));
}

// ---------------------------------------------------- Tier Zero settings files

/// A Tier Zero settings file (`pathwarden.tierzero.v1`) for DC `host` of
/// PKI.LOCAL. `None` is a value that is not set.
fn tierzero_file(host: &str, read_at: &str, binding: Option<i64>, mapping: Option<i64>) -> String {
    tierzero_file_on(host, read_at, Some("20348.2700"), binding, mapping)
}

/// [`tierzero_file`] for a DC of OS build `build` (`None`: not recorded).
fn tierzero_file_on(
    host: &str,
    read_at: &str,
    build: Option<&str>,
    binding: Option<i64>,
    mapping: Option<i64>,
) -> String {
    let value = |name: &str, key: &str, v: Option<i64>| {
        serde_json::json!({
            "name": name,
            "path": format!("HKLM\\SYSTEM\\CurrentControlSet\\{key}"),
            "present": v.is_some(),
            "value": v,
            "error": null,
        })
    };
    serde_json::json!({
        "schema": "pathwarden.tierzero.v1",
        "domain": "pki.local",
        "dc": {"hostname": host, "dns_name": format!("{}.pki.local", host.to_ascii_lowercase()),
               "os_build": build},
        "read_at": read_at,
        "values": [
            value("StrongCertificateBindingEnforcement", "Services\\Kdc", binding),
            value("CertificateMappingMethods", "Control\\SecurityProviders\\Schannel", mapping),
        ],
    })
    .to_string()
}

/// The collection time collectors put in file names: 2026-10-13 08:30 UTC.
const STAMP: &str = "20261013083000_";

/// DC01's computer file with its registry block set to `registry`
/// (SharpHound's `DCRegistryData`). With `dc02`, a second domain controller
/// DC02 whose registry was not read.
fn computers_with(registry: &serde_json::Value, text: &str, dc02: bool) -> String {
    let mut v: serde_json::Value = serde_json::from_str(text).unwrap();
    let data = v["data"].as_array_mut().unwrap();
    for c in data.iter_mut() {
        if c.get("DCRegistryData").is_some_and(|d| !d.is_null()) {
            c["DCRegistryData"] = registry.clone();
        }
    }
    if dc02 {
        let mut second = data.iter().find(|c| c["IsDC"] == true).unwrap().clone();
        second["ObjectIdentifier"] = "S-1-5-21-5000-5000-5000-1003".into();
        second["Properties"]["name"] = "DC02.PKI.LOCAL".into();
        second["DCRegistryData"] = uncollected();
        data.push(second);
        v["meta"]["count"] = (v["data"].as_array().unwrap().len()).into();
    }
    v.to_string()
}

/// The fixture in a temp folder, with DC01's registry block set to
/// `registry`, file names prefixed with `stamp` (the collection time
/// collectors put there), and `extra` files added.
fn fixture_with(
    tag: &str,
    registry: serde_json::Value,
    stamp: &str,
    extra: &[(&str, String)],
) -> (AdGraph, IngestStats) {
    fixture_full(tag, registry, stamp, extra, false)
}

fn fixture_full(
    tag: &str,
    registry: serde_json::Value,
    stamp: &str,
    extra: &[(&str, String)],
    dc02: bool,
) -> (AdGraph, IngestStats) {
    fixture_opts(tag, registry, stamp, extra, dc02, &LoadOptions::default())
}

fn fixture_opts(
    tag: &str,
    registry: serde_json::Value,
    stamp: &str,
    extra: &[(&str, String)],
    dc02: bool,
    opts: &LoadOptions,
) -> (AdGraph, IngestStats) {
    let src = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/adcs");
    let dir = std::env::temp_dir().join(format!("pathwarden-adcs-t0-{tag}-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    for entry in std::fs::read_dir(&src).unwrap() {
        let path = entry.unwrap().path();
        let file = path.file_name().unwrap().to_string_lossy().to_string();
        let mut text = std::fs::read_to_string(&path).unwrap();
        if file == "pki_computers.json" {
            text = computers_with(&registry, &text, dc02);
        }
        std::fs::write(dir.join(format!("{stamp}{file}")), text).unwrap();
    }
    for (name, text) in extra {
        std::fs::write(dir.join(name), text).unwrap();
    }
    let out = load(std::slice::from_ref(&dir), opts).expect("fixture loads");
    let _ = std::fs::remove_dir_all(&dir);
    out
}

/// SharpHound without rights to read DC01's registry.
fn uncollected() -> serde_json::Value {
    serde_json::json!({
        "CertificateMappingMethods": {"Value": 0, "Collected": false, "FailureReason": "access denied"},
        "StrongCertificateBindingEnforcement": {"Value": 0, "Collected": false, "FailureReason": "access denied"},
    })
}

fn pw020(g: &AdGraph, stats: &IngestStats) -> Vec<findings::Finding> {
    let settings = RuleSettings::default();
    let ctx = Context::new(g, &stats.trusts, &settings);
    findings::evaluate(&ctx, &[])
        .into_iter()
        .filter(|f| f.rule == "PW-020")
        .collect()
}

#[test]
fn without_dc_settings_esc9_is_unverified_and_completeness_says_so() {
    let (g, stats) = fixture_with("none", uncollected(), "", &[]);
    let by = instances(&g);
    let i = only(&by, Esc::Esc9a);
    assert!(i.targets.is_empty());
    assert_eq!(i.unverified.len(), 1);
    // ESC9a, and ESC10a since the Schannel value is unknown too.
    let f = pw020(&g, &stats);
    assert_eq!(f.len(), 2);
    for f in &f {
        assert!(f.title.ends_with("(unverified)"), "{}", f.title);
        assert!(f.summary.contains("Get-PathwardenTierZeroSettings.ps1"));
    }

    let c = pathwarden_core::dcsettings::completeness(&g, 0);
    assert_eq!(c.len(), 1);
    assert_eq!(c[0].domain, "PKI.LOCAL");
    assert_eq!(
        (c[0].read, c[0].domain_controllers, c[0].from_file),
        (0, 1, 0)
    );
    assert_eq!(c[0].missing, ["DC01.PKI.LOCAL"]);
    assert!(!c[0].is_complete());
}

#[test]
fn tierzero_file_verifies_esc9_as_an_attack_path() {
    let file = tierzero_file("DC01", "2026-10-13T08:30:00Z", Some(1), Some(0x18));
    let (g, stats) = fixture_with(
        "weak",
        uncollected(),
        STAMP,
        &[("pathwarden-tierzero-DC01.pki.local.json", file)],
    );
    assert_eq!(stats.dc_settings.len(), 1, "{:?}", stats.skipped_files);
    let st = &stats.dc_settings[0];
    assert_eq!(st.matched.as_deref(), Some("DC01.PKI.LOCAL"));
    assert_eq!(
        st.applied,
        [
            "StrongCertificateBindingEnforcement",
            "CertificateMappingMethods"
        ]
    );
    assert!(st.kept.is_empty());

    let by = instances(&g);
    let i = only(&by, Esc::Esc9a);
    assert_eq!(i.targets.len(), 1);
    assert!(i.unverified.is_empty());
    assert!(has_edge(&g, EdgeKind::AdcsEsc9a));
    assert!(!by.contains_key(&Esc::Esc10a), "0x18 has no UPN mapping");
    let f = pw020(&g, &stats);
    assert_eq!(f.len(), 1);
    assert!(!f[0].title.contains("unverified"), "{}", f[0].title);
    assert_eq!(f[0].category, findings::Category::AttackPath);

    let read_at = pathwarden_core::dcsettings::parse_utc("2026-10-13T08:30:00Z").unwrap();
    let c = pathwarden_core::dcsettings::completeness(&g, read_at);
    assert_eq!(
        (c[0].read, c[0].domain_controllers, c[0].from_file),
        (1, 1, 1)
    );
    assert!(c[0].missing.is_empty() && c[0].is_complete());
    // A year later the file is stale.
    let c = pathwarden_core::dcsettings::completeness(&g, read_at + 365 * 86_400);
    assert_eq!(c[0].stale, ["DC01.PKI.LOCAL"]);
    assert!(!c[0].is_complete());
}

