#[test]
fn tierzero_file_in_the_zip_is_read() {
    use std::io::Write;
    let src = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../testdata/adcs");
    let dir = std::env::temp_dir().join(format!("pathwarden-adcs-t0-zip-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let zip_path = dir.join("20261013083000_PKI_BloodHound.zip");
    let mut zip = zip::ZipWriter::new(std::fs::File::create(&zip_path).unwrap());
    let opts = zip::write::SimpleFileOptions::default();
    for entry in std::fs::read_dir(&src).unwrap() {
        let path = entry.unwrap().path();
        let mut text = std::fs::read_to_string(&path).unwrap();
        if path.file_name().unwrap() == "pki_computers.json" {
            text = computers_with(&uncollected(), &text, false);
        }
        zip.start_file(path.file_name().unwrap().to_string_lossy(), opts)
            .unwrap();
        zip.write_all(text.as_bytes()).unwrap();
    }
    zip.start_file("pathwarden-tierzero-DC01.json", opts)
        .unwrap();
    let file = tierzero_file("DC01", "2026-10-13T09:00:00Z", Some(1), Some(0x18));
    zip.write_all(file.as_bytes()).unwrap();
    zip.finish().unwrap();
    let (g, stats) = load(std::slice::from_ref(&zip_path), &LoadOptions::default()).unwrap();
    let _ = std::fs::remove_dir_all(&dir);
    assert_eq!(stats.dc_settings.len(), 1, "{:?}", stats.skipped_files);
    assert_eq!(
        stats.dc_settings[0].matched.as_deref(),
        Some("DC01.PKI.LOCAL")
    );
    assert!(only(&instances(&g), Esc::Esc9a).unverified.is_empty());
}

