#[test]
fn the_newer_of_collection_and_file_wins() {
    // SharpHound read full enforcement on 2026-10-13; an older file says 1.
    let strong = serde_json::json!({
        "CertificateMappingMethods": {"Value": 24, "Collected": true},
        "StrongCertificateBindingEnforcement": {"Value": 2, "Collected": true},
    });
    let older = tierzero_file("DC01", "2026-01-01T00:00:00Z", Some(1), Some(0x18));
    let (g, stats) = fixture_with(
        "older",
        strong.clone(),
        "20261013083000_",
        &[("pathwarden-tierzero-DC01.json", older)],
    );
    assert_eq!(
        stats.dc_settings[0].kept,
        [
            "StrongCertificateBindingEnforcement",
            "CertificateMappingMethods"
        ]
    );
    assert!(stats.dc_settings[0].applied.is_empty());
    assert!(!instances(&g).contains_key(&Esc::Esc9a));

    // A file read after the collection wins.
    // (Not after today's clock: a read time in the future counts as none.)
    let newer = tierzero_file("DC01", "2026-10-13T12:00:00Z", Some(1), Some(0x18));
    let (g, stats) = fixture_with(
        "newer",
        strong,
        "20261013083000_",
        &[("pathwarden-tierzero-DC01.json", newer)],
    );
    assert_eq!(stats.dc_settings[0].applied.len(), 2);
    assert_eq!(only(&instances(&g), Esc::Esc9a).targets.len(), 1);
}

#[test]
fn a_stale_file_never_closes_esc9_but_still_opens_it() {
    // Read in 2024, collection in October 2026: full enforcement is ignored.
    let strong = tierzero_file("DC01", "2024-01-01T00:00:00Z", Some(2), Some(0x18));
    let (g, stats) = fixture_with(
        "stale-strong",
        uncollected(),
        STAMP,
        &[("pathwarden-tierzero-DC01.json", strong)],
    );
    let st = &stats.dc_settings[0];
    assert!(st.applied.is_empty());
    assert_eq!(
        st.ignored,
        [
            "StrongCertificateBindingEnforcement",
            "CertificateMappingMethods"
        ]
    );
    assert!(
        st.notes.iter().any(|n| n.contains("90 days")),
        "{:?}",
        st.notes
    );
    assert_eq!(only(&instances(&g), Esc::Esc9a).unverified.len(), 1);
    let collected = stats.collected_at.unwrap();
    let c = pathwarden_core::dcsettings::completeness(&g, collected);
    assert_eq!(c[0].stale, ["DC01.PKI.LOCAL"]);
    assert_eq!(c[0].missing, ["DC01.PKI.LOCAL"]);
    assert_eq!(c[0].from_file, 0);

    // Weak binding from the same old file still shows the attack path.
    let weak = tierzero_file("DC01", "2024-01-01T00:00:00Z", Some(1), Some(0x18));
    let (g, stats) = fixture_with(
        "stale-weak",
        uncollected(),
        STAMP,
        &[("pathwarden-tierzero-DC01.json", weak)],
    );
    let st = &stats.dc_settings[0];
    assert_eq!(st.applied, ["StrongCertificateBindingEnforcement"]);
    assert_eq!(st.ignored, ["CertificateMappingMethods"]);
    let by = instances(&g);
    assert_eq!(only(&by, Esc::Esc9a).targets.len(), 1);
    // The Schannel value is still unknown: ESC10a stays unverified.
    assert!(only(&by, Esc::Esc10a).targets.is_empty());
}

#[test]
fn an_undated_file_does_not_beat_the_collection() {
    let strong = serde_json::json!({
        "CertificateMappingMethods": {"Value": 24, "Collected": true},
        "StrongCertificateBindingEnforcement": {"Value": 2, "Collected": true},
    });
    let mut file: serde_json::Value =
        serde_json::from_str(&tierzero_file("DC01", "x", Some(1), Some(0x1f))).unwrap();
    file.as_object_mut().unwrap().remove("read_at");
    let (g, stats) = fixture_with(
        "undated",
        strong,
        STAMP,
        &[("pathwarden-tierzero-DC01.json", file.to_string())],
    );
    let st = &stats.dc_settings[0];
    assert!(st.applied.is_empty(), "{st:?}");
    assert_eq!(st.kept.len(), 2);
    assert!(!instances(&g).contains_key(&Esc::Esc9a));

    // A malformed time is the same as none; with nothing collected, only
    // the weak values are used.
    let bad = tierzero_file("DC01", "13/10/2026", Some(2), Some(0x1f));
    let (_, stats) = fixture_with(
        "badtime",
        uncollected(),
        STAMP,
        &[("pathwarden-tierzero-DC01.json", bad)],
    );
    let st = &stats.dc_settings[0];
    assert_eq!(st.applied, ["CertificateMappingMethods"]);
    assert_eq!(st.ignored, ["StrongCertificateBindingEnforcement"]);
    assert!(
        st.notes.iter().any(|n| n.contains("no read time")),
        "{:?}",
        st.notes
    );
}

