#[test]
fn the_wall_clock_from_load_options_judges_files_without_a_collection_time() {
    let file = tierzero_file("DC01", "2026-10-13T08:30:00Z", Some(2), Some(0x18));
    let at = |t: &str| LoadOptions {
        now: pathwarden_core::dcsettings::parse_utc(t),
        ..LoadOptions::default()
    };
    // No collection time in the file names: the clock decides.
    let (g, stats) = fixture_opts(
        "clock-fresh",
        uncollected(),
        "",
        &[("pathwarden-tierzero-DC01.json", file.clone())],
        false,
        &at("2026-10-20T00:00:00Z"),
    );
    assert_eq!(stats.dc_settings[0].applied.len(), 2);
    assert!(!instances(&g).contains_key(&Esc::Esc9a));
    // A year on, the same file is stale and closes nothing.
    let (g, stats) = fixture_opts(
        "clock-stale",
        uncollected(),
        "",
        &[("pathwarden-tierzero-DC01.json", file.clone())],
        false,
        &at("2027-10-20T00:00:00Z"),
    );
    assert_eq!(stats.dc_settings[0].ignored.len(), 2);
    assert_eq!(only(&instances(&g), Esc::Esc9a).unverified.len(), 1);
    // Read "in the future" (a wrong clock): counts as undated.
    let (g, stats) = fixture_opts(
        "clock-future",
        uncollected(),
        "",
        &[("pathwarden-tierzero-DC01.json", file)],
        false,
        &at("2026-10-01T00:00:00Z"),
    );
    let st = &stats.dc_settings[0];
    assert_eq!(st.read_at, None);
    assert_eq!(st.ignored.len(), 2);
    assert!(
        st.notes.iter().any(|n| n.contains("in the future")),
        "{:?}",
        st.notes
    );
    assert_eq!(only(&instances(&g), Esc::Esc9a).unverified.len(), 1);
}

