#[test]
fn compatibility_mode_ends_with_the_september_2025_update() {
    // SharpHound read binding 1 (and Schannel 0x18) at collection time.
    let weak = serde_json::json!({
        "CertificateMappingMethods": {"Value": 24, "Collected": true},
        "StrongCertificateBindingEnforcement": {"Value": 1, "Collected": true},
    });
    // A file without values: only its build is used.
    let build_only = |read_at: &str, build: &str| {
        let mut f: serde_json::Value =
            serde_json::from_str(&tierzero_file_on("DC01", read_at, Some(build), None, None))
                .unwrap();
        f["values"] = serde_json::json!([]);
        f.to_string()
    };
    let (g, _) = fixture_with(
        "sep2025",
        weak.clone(),
        STAMP,
        &[(
            "pathwarden-tierzero-DC01.json",
            build_only("2026-10-13T08:30:00Z", "20348.4171"),
        )],
    );
    assert!(!instances(&g).contains_key(&Esc::Esc9a));
    let (g, _) = fixture_with(
        "aug2025",
        weak.clone(),
        STAMP,
        &[(
            "pathwarden-tierzero-DC01.json",
            build_only("2026-10-13T08:30:00Z", "20348.4170"),
        )],
    );
    assert_eq!(only(&instances(&g), Esc::Esc9a).targets.len(), 1);
    // From a stale file, the patched build doesn't close it.
    let (g, _) = fixture_with(
        "sep2025-stale",
        weak,
        STAMP,
        &[(
            "pathwarden-tierzero-DC01.json",
            build_only("2024-01-01T00:00:00Z", "20348.4171"),
        )],
    );
    assert_eq!(only(&instances(&g), Esc::Esc9a).targets.len(), 1);

    // A build-only file is a source in the completeness report.
    let (g, stats) = fixture_with(
        "build-only-source",
        weak_binding(),
        STAMP,
        &[(
            "pathwarden-tierzero-DC01.json",
            build_only("2026-10-13T08:30:00Z", "20348.4170"),
        )],
    );
    assert!(stats.dc_settings[0].os_build_used);
    let c = pathwarden_core::dcsettings::completeness(&g, stats.collected_at.unwrap());
    assert_eq!((c[0].read, c[0].from_file), (1, 1));
}

/// SharpHound's reading of DC01: binding 1, Schannel 0x18.
fn weak_binding() -> serde_json::Value {
    serde_json::json!({
        "CertificateMappingMethods": {"Value": 24, "Collected": true},
        "StrongCertificateBindingEnforcement": {"Value": 1, "Collected": true},
    })
}

/// SharpHound's reading of DC01: neither value set.
fn sharphound_unset() -> serde_json::Value {
    serde_json::json!({
        "CertificateMappingMethods": {"Value": -1, "Collected": true},
        "StrongCertificateBindingEnforcement": {"Value": -1, "Collected": true},
    })
}

fn rule(g: &AdGraph, stats: &IngestStats, id: &str) -> Vec<findings::Finding> {
    let settings = RuleSettings::default();
    let ctx = Context::new(g, &stats.trusts, &settings);
    findings::evaluate(&ctx, &[])
        .into_iter()
        .filter(|f| f.rule == id)
        .collect()
}

